WITH with_windows AS (SELECT *, MIN(quantity) OVER (PARTITION BY store_id, product_id) AS store_id_min_quantity, STDDEV_SAMP(quantity) OVER (PARTITION BY product_id, store_id) AS product_id_stddev_samp_quantity, DENSE_RANK() OVER w_running AS quantity_dense_rank FROM inventory WINDOW w_running AS (ORDER BY quantity ASC NULLS FIRST)) SELECT store_id, COUNT(*) AS event_count, STDDEV_SAMP(quantity) AS quantity_stddev FROM with_windows GROUP BY store_id ORDER BY event_count DESC NULLS LAST;
